# Snap configuration to application environment mapping.
#
# Format: ENV_KEY SNAP_CONFIG_KEY [condition]
# Conditions:
#   always       apply whenever the snap config key has a non-empty value
#   tls-enabled apply only when tls.enabled is truthy
#
# Keep snap config-to-env wiring in this table so new options are reviewed in
# one place instead of being scattered across shell statements.
CHARM_REGISTRY_LISTEN listen always
CHARM_REGISTRY_OCI_LISTEN oci.listen always
CHARM_REGISTRY_PUBLIC_API_URL public-api-url always
CHARM_REGISTRY_PUBLIC_STORAGE_URL public-storage-url always
CHARM_REGISTRY_PUBLIC_REGISTRY_URL public-registry-url always
CHARM_REGISTRY_API_TLS_CERT_FILE tls.cert-file tls-enabled
CHARM_REGISTRY_API_TLS_KEY_FILE tls.key-file tls-enabled
CHARM_REGISTRY_OCI_INTERNAL_URL oci.internal-url always
CHARM_REGISTRY_DATABASE_URL database.url always
CHARM_REGISTRY_DATABASE_BACKEND database.backend always
CHARM_REGISTRY_STORAGE_BACKEND storage.backend always
CHARM_REGISTRY_OCI_STORAGE_BACKEND oci.storage.backend always
CHARM_REGISTRY_S3_ENDPOINT storage.s3.endpoint always
CHARM_REGISTRY_S3_BUCKET storage.s3.bucket always
CHARM_REGISTRY_S3_REGION storage.s3.region always
CHARM_REGISTRY_S3_ACCESS_KEY_ID storage.s3.access-key-id always
CHARM_REGISTRY_S3_SECRET_ACCESS_KEY storage.s3.secret-access-key always
CHARM_REGISTRY_S3_USE_PATH_STYLE storage.s3.use-path-style always
CHARM_REGISTRY_S3_DISABLE_TLS storage.s3.disable-tls always
CHARM_REGISTRY_OCI_S3_ENDPOINT oci.storage.s3.endpoint always
CHARM_REGISTRY_OCI_S3_BUCKET oci.storage.s3.bucket always
CHARM_REGISTRY_OCI_S3_PREFIX oci.storage.s3.prefix always
CHARM_REGISTRY_OCI_S3_REGION oci.storage.s3.region always
CHARM_REGISTRY_OCI_S3_ACCESS_KEY oci.storage.s3.access-key always
CHARM_REGISTRY_OCI_S3_SECRET_KEY oci.storage.s3.secret-key always
CHARM_REGISTRY_OCI_S3_USE_PATH_STYLE oci.storage.s3.use-path-style always
CHARM_REGISTRY_OCI_SECRET_KEY oci.secret-key always
CHARM_REGISTRY_OCI_TLS_CERT_FILE oci.tls.cert-file always
CHARM_REGISTRY_OCI_TLS_KEY_FILE oci.tls.key-file always
CHARM_REGISTRY_OCI_PROJECT_PREFIX oci.project-prefix always
CHARM_REGISTRY_OCI_PULL_ROBOT_PREFIX oci.pull-robot-prefix always
CHARM_REGISTRY_OCI_PUSH_ROBOT_PREFIX oci.push-robot-prefix always
CHARM_REGISTRY_OIDC_ISSUER_URL oidc.issuer-url always
CHARM_REGISTRY_OIDC_CLIENT_ID oidc.client-id always
CHARM_REGISTRY_OIDC_USERNAME_CLAIM oidc.username-claim always
CHARM_REGISTRY_OIDC_DISPLAY_NAME_CLAIM oidc.display-name-claim always
CHARM_REGISTRY_OIDC_EMAIL_CLAIM oidc.email-claim always
CHARM_REGISTRY_ADMIN_SUBJECTS admin.subjects always
CHARM_REGISTRY_ADMIN_EMAILS admin.emails always
CHARM_REGISTRY_ADMIN_USERNAMES admin.usernames always
CHARM_REGISTRY_ENABLE_INSECURE_DEV_AUTH insecure-dev-auth always
CHARM_REGISTRY_CHARMHUB_URL charmhub.url always
CHARM_REGISTRY_CHARMHUB_SYNC_INTERVAL charmhub.sync-interval always
CHARM_REGISTRY_CHARMHUB_MAX_ARTIFACT_BYTES charmhub.max-artifact-bytes always
CHARM_REGISTRY_MAX_ARCHIVE_FILE_BYTES limits.max-archive-file-bytes always
CHARM_REGISTRY_MAX_UPLOAD_BYTES limits.max-upload-bytes always
CHARM_REGISTRY_IP_RATE_LIMIT rate-limit.ip-limit always
CHARM_REGISTRY_IP_RATE_WINDOW rate-limit.ip-window always
CHARM_REGISTRY_TOKEN_RATE_LIMIT rate-limit.token-limit always
CHARM_REGISTRY_TOKEN_RATE_WINDOW rate-limit.token-window always
